mapper.update:
UPDATE GESTURE_THREAD_POST_COMMENT SET comment = #{comment}, modDate = NOW()
WHERE commentNo = ${commentNo}
  AND (commentWriter = #{commentWriter} OR #{commentWriter} = 0)

mapper.delete:
UPDATE GESTURE_THREAD_POST_COMMENT SET isRemove = 1, rmDate = NOW()
WHERE threadNo = ${threadNo}
  AND postNo = ${postNo}
  AND commentNo = ${commentNo}
  AND (commentWriter = #{commentWriter} OR #{commentWriter} = 0)
